//! Interoperability checks against structures saved by the official Minecraft server.
//!
//! These files are not generated by FuryBuilder's serializer. They were captured from a
//! disposable Minecraft Java 1.21.4 server, so parsing them exercises the real format,
//! including palette order, sparse air and block-entity payloads.

use world_domain::BlockState;
use world_io::{
    default_version_profile, inspect_java_structure, read_java_structure, read_verified_import,
    write_java_structure, JavaStructureError,
};

const PLAIN: &[u8] = include_bytes!("../../../fixtures/java-1.21.4/structures/plain.nbt");
const CHEST_BOUNDARY: &[u8] =
    include_bytes!("../../../fixtures/java-1.21.4/structures/chest_boundary.nbt");

#[test]
fn official_plain_structure_round_trips_semantically() {
    let parsed = read_java_structure(PLAIN).expect("official plain structure parses");
    let target = default_version_profile();
    assert_eq!(parsed.inspection.data_version, target.data_version);
    assert_eq!(parsed.inspection.target_data_version, target.data_version);
    assert_eq!(parsed.inspection.size, [1, 2, 1]);
    assert_eq!(parsed.inspection.volume, 2);
    assert_eq!(parsed.inspection.palette_size, 2);
    assert_eq!(parsed.inspection.non_air_blocks, 2);
    assert!(parsed.inspection.compatible);
    assert_eq!(parsed.author, None);
    assert_eq!(
        parsed.structure.palette[0],
        BlockState::new("minecraft:stone_bricks", Default::default()).unwrap()
    );
    let stairs: BlockState =
        "minecraft:oak_stairs[facing=east,half=bottom,shape=straight,waterlogged=false]"
            .parse()
            .unwrap();
    assert_eq!(parsed.structure.palette[1], stairs);
    assert_eq!(parsed.structure.blocks[0].pos, [0, 0, 0]);
    assert_eq!(parsed.structure.blocks[1].pos, [0, 1, 0]);
    assert_eq!(
        read_verified_import(PLAIN)
            .expect("official plain structure passes strict import")
            .structure,
        parsed.structure
    );

    let reencoded = write_java_structure(&parsed.structure, "FuryBuilder").unwrap();
    let reparsed = read_java_structure(&reencoded).expect("FuryBuilder output parses back");
    assert_eq!(reparsed.structure, parsed.structure);
    assert_eq!(reparsed.inspection.non_air_blocks, 2);
}

#[test]
fn official_structure_with_block_entity_is_refused_instead_of_dropped() {
    let inspection = inspect_java_structure(CHEST_BOUNDARY).expect("inspection is structural");
    assert_eq!(
        inspection.data_version,
        default_version_profile().data_version
    );
    assert_eq!(inspection.size, [2, 2, 2]);
    assert_eq!(inspection.non_air_blocks, 6);
    assert_eq!(inspection.block_entities, 1);
    assert!(!inspection.compatible);
    assert!(inspection
        .warnings
        .iter()
        .any(|warning| warning.contains("block entities")));
    assert!(inspection
        .unknown_tags
        .iter()
        .any(|tag| tag.ends_with(".nbt")));

    assert!(matches!(
        read_java_structure(CHEST_BOUNDARY),
        Err(JavaStructureError::UnsupportedContent(_))
    ));
    assert!(read_verified_import(CHEST_BOUNDARY).is_err());
}
